const input=$json.body??$json;
const classification=String(input.classification??'').toLowerCase();
const status=String(input.status??'').toLowerCase();
const amount=Number(input.counteroffer_amount??0);
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao??0);
const hasMao=mao>0;
const near=hasMao&&amount>mao&&amount<=mao*1.10;
const above=hasMao&&amount>mao*1.10;
const accepted=['accepted','acceptance','seller_acceptance'].includes(classification)||status==='accepted';
const rejected=['rejected','declined'].includes(classification)||status==='rejected';
const timeout=['timeout','response_timeout','no_response'].includes(status)||classification==='no_response';
const question=['question','other_response'].includes(classification);
const dnc=classification==='dnc'||input.dnc===true||status==='blocked_dnc';
let decision='needs_review',next='WF-126',reason='insufficient negotiation evidence';
if(dnc){decision='blocked_dnc';next='WF-126';reason='DNC or contact restriction';}
else if(timeout){decision='timeout_followup';next='WF-320';reason='seller response window expired';}
else if(rejected){decision='reengage';next='WF-320';reason='seller rejected current offer';}
else if(accepted&&hasMao){decision='contract_ready';next='WF-319';reason='seller accepted within protected MAO';}
else if(classification==='counteroffer'&&hasMao&&amount>0){
  if(amount<=mao){decision='counteroffer_within_mao';next='WF-319';reason='counteroffer is within dynamic MAO';}
  else if(near){decision='counteroffer_near_mao';next='WF-319';reason='counteroffer is within controlled negotiation band';}
  else if(above){decision='counteroffer_above_mao';next='WF-320';reason='counteroffer exceeds protected negotiation band';}
}
else if(question){decision='clarification_response';next='WF-319';reason='seller question requires negotiation response';}
return [{json:{...input,workflow_id:'WF-318',workflow_name:'Seller Response / Timeout → Negotiation Decision Controller',negotiation_decision:decision,decision_reason:reason,mao_protected:hasMao,dynamic_mao:mao,counteroffer_amount:amount||null,mao_relationship:amount===0?'unknown':above?'above_110_percent_mao':near?'near_mao':'within_mao',next_workflow:next,human_review_required:['counteroffer_near_mao','counteroffer_above_mao','needs_review','reengage'].includes(decision),crm_activity:{activity_type:'negotiation_decision',deal_id:input.deal_id,lead_id:input.lead_id,property_id:input.property_id,status:decision,classification,counteroffer_amount:amount||null,reason}}}];
